export default "// Smooth, complex manifolds can be created using the warp() function.\n// This example recreates the Exploitable Heart by Emmett Lalish:\n// https://www.thingiverse.com/thing:6190\n// It also demonstrates the use of setMorph to animate a warping function.\n\nimport {GLTFNode, Manifold, setMorphStart} from 'manifold-3d/manifoldCAD';\n\n\nconst func = (v) => {\n  const x2 = v[0] * v[0];\n  const y2 = v[1] * v[1];\n  const z = v[2];\n  const z2 = z * z;\n  const a = x2 + 9 / 4 * y2 + z2;\n  const b = z * z2 * (x2 + 9 / 80 * y2);\n  const a2 = a * a;\n  const a3 = a * a2;\n\n  const step = (r) => {\n    const r2 = r * r;\n    const r4 = r2 * r2;\n    // Taubin's function: https://mathworld.wolfram.com/HeartSurface.html\n    const f = a3 * r4 * r2 - b * r4 * r - 3 * a2 * r4 + 3 * a * r2 - 1;\n    // Derivative\n    const df = 6 * a3 * r4 * r - 5 * b * r4 - 12 * a2 * r2 * r + 6 * a * r;\n    return f / df;\n  };\n  // Newton's method for root finding\n  let r = 1.5;\n  let dr = 1;\n  while (Math.abs(dr) > 0.0001) {\n    dr = step(r);\n    r -= dr;\n  }\n  // Update radius\n  v[0] *= r;\n  v[1] *= r;\n  v[2] *= r;\n};\n\nconst ball = Manifold.sphere(1, 200);\n\nconst heart = ball.warp(func);\nconst box = heart.boundingBox();\nconst scale = 100 / (box.max[0] - box.min[0]);\n\nsetMorphStart(ball, func);\nconst node = new GLTFNode();\nnode.manifold = ball;\nnode.scale = [scale, scale, scale];\nnode.translation = [0, 0, scale];\n\nsetAnimationDuration(5);  // seconds\nsetAnimationMode('ping-pong');\n\nexport default node;"